import{c as t,Q as e,j as o,m as l}from"./chunks/framework.CHJbb1iY.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"outline":[2,3],"sidebar":"tue","aside":"right"},"headers":[],"relativePath":"docs/Java/第一阶段/基本语法/12.标识符和保留字.md","filePath":"docs/Java/第一阶段/基本语法/12.标识符和保留字.md"}'),r={name:"docs/Java/第一阶段/基本语法/12.标识符和保留字.md"};function n(s,a,i,h,c,d){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 style="text-align:center;font-weight:bold;">标识符和保留字</h1><hr><h2 id="标识符" tabindex="-1">标识符 <a class="header-anchor" href="#标识符" aria-label="Permalink to &quot;标识符&quot;">​</a></h2><h3 id="基本介绍" tabindex="-1">基本介绍 <a class="header-anchor" href="#基本介绍" aria-label="Permalink to &quot;基本介绍&quot;">​</a></h3><blockquote><h4 id="_1-java-对各种变量、方法和类等命名时使用的字符序列称为标识符" tabindex="-1">（1） Java 对各种<span style="color:red;">变量、方法和类</span>等命名时使用的字符序列称为<span style="color:red;">标识符</span> <a class="header-anchor" href="#_1-java-对各种变量、方法和类等命名时使用的字符序列称为标识符" aria-label="Permalink to &quot;（1） Java 对各种&lt;span style=&quot;color:red&quot;&gt;变量、方法和类&lt;/span&gt;等命名时使用的字符序列称为&lt;span style=&quot;color:red&quot;&gt;标识符&lt;/span&gt;&quot;">​</a></h4><h4 id="_2-凡是自己可以起名字的地方都可以使用标识符-例如-int-num1-90" tabindex="-1">（2） 凡是自己可以起名字的地方都可以使用标识符， 例如：int num1 = 90; <a class="header-anchor" href="#_2-凡是自己可以起名字的地方都可以使用标识符-例如-int-num1-90" aria-label="Permalink to &quot;（2） 凡是自己可以起名字的地方都可以使用标识符， 例如：int num1 = 90;&quot;">​</a></h4></blockquote><h3 id="命名规则" tabindex="-1">命名规则 <a class="header-anchor" href="#命名规则" aria-label="Permalink to &quot;命名规则&quot;">​</a></h3><blockquote><h4 id="_1-由-26-个英文字母-大小写-、0-9、或-组成。" tabindex="-1">（1） 由 26 个英文字母（大小写）、0-9、或 <span style="color:red;">$</span> 组成。 <a class="header-anchor" href="#_1-由-26-个英文字母-大小写-、0-9、或-组成。" aria-label="Permalink to &quot;（1） 由 26 个英文字母（大小写）、0-9、或 &lt;span style=&quot;color:red&quot;&gt;$&lt;/span&gt; 组成。&quot;">​</a></h4><h4 id="_2-不能以数字开头-例如-int-3ab-1-会出错。" tabindex="-1">（2） <span style="color:red;">不能以数字开头</span>，例如：int 3ab = 1; 会出错。 <a class="header-anchor" href="#_2-不能以数字开头-例如-int-3ab-1-会出错。" aria-label="Permalink to &quot;（2） &lt;span style=&quot;color:red&quot;&gt;不能以数字开头&lt;/span&gt;，例如：int 3ab = 1; 会出错。&quot;">​</a></h4><h4 id="_3-不能使用关键字、保留字-但可以包含关键字和保留字。-例如-int-totalnum-10-和-int-n-90-都是合法的。" tabindex="-1">（3） <span style="color:red;">不能使用关键字、保留字</span>，但<span style="color:red;">可以包含</span>关键字和保留字。 例如：int totalNum = 10; 和 int n = 90; 都是合法的。 <a class="header-anchor" href="#_3-不能使用关键字、保留字-但可以包含关键字和保留字。-例如-int-totalnum-10-和-int-n-90-都是合法的。" aria-label="Permalink to &quot;（3） &lt;span style=&quot;color:red&quot;&gt;不能使用关键字、保留字&lt;/span&gt;，但&lt;span style=&quot;color:red&quot;&gt;可以包含&lt;/span&gt;关键字和保留字。 例如：int totalNum = 10; 和 int n = 90; 都是合法的。&quot;">​</a></h4><h4 id="_4-标识符不能包含空格。-例如-int-a-b-90-会出错。" tabindex="-1">（4）标识符<span style="color:red;">不能包含空格</span>。 例如：int a b = 90; 会出错。 <a class="header-anchor" href="#_4-标识符不能包含空格。-例如-int-a-b-90-会出错。" aria-label="Permalink to &quot;（4）标识符&lt;span style=&quot;color:red&quot;&gt;不能包含空格&lt;/span&gt;。 例如：int a b = 90; 会出错。&quot;">​</a></h4><h4 id="_5-不能有-例如-int-h-x-10-这是错的-可以使用下划线" tabindex="-1">（5） <span style="color:red;">不能有 <code>-</code></span>，例如：int h-x = 10;，这是错的，可以使用下划线 <a class="header-anchor" href="#_5-不能有-例如-int-h-x-10-这是错的-可以使用下划线" aria-label="Permalink to &quot;（5） &lt;span style=&quot;color:red&quot;&gt;不能有 `-` &lt;/span&gt;，例如：int h-x = 10;，这是错的，可以使用下划线&quot;">​</a></h4></blockquote><hr><h2 id="命名规范" tabindex="-1">命名规范 <a class="header-anchor" href="#命名规范" aria-label="Permalink to &quot;命名规范&quot;">​</a></h2><h3 id="包名" tabindex="-1">包名 <a class="header-anchor" href="#包名" aria-label="Permalink to &quot;包名&quot;">​</a></h3><blockquote><h4 id="多单词组成时所有字母都小写-aaa-bbb-ccc-例如-com-hsp-crm" tabindex="-1">多单词组成时<span style="color:red;">所有字母都小写</span>：aaa.bbb.ccc 例如：com.hsp.crm <a class="header-anchor" href="#多单词组成时所有字母都小写-aaa-bbb-ccc-例如-com-hsp-crm" aria-label="Permalink to &quot;多单词组成时&lt;span style=&quot;color:red&quot;&gt;所有字母都小写&lt;/span&gt;：aaa.bbb.ccc 例如：com.hsp.crm&quot;">​</a></h4></blockquote><h3 id="类名、接口名" tabindex="-1">类名、接口名 <a class="header-anchor" href="#类名、接口名" aria-label="Permalink to &quot;类名、接口名&quot;">​</a></h3><blockquote><h4 id="驼峰命名法-大驼峰" tabindex="-1">驼峰命名法（<span style="color:red;">大驼峰</span>） <a class="header-anchor" href="#驼峰命名法-大驼峰" aria-label="Permalink to &quot;驼峰命名法（&lt;span style=&quot;color:red&quot;&gt;大驼峰&lt;/span&gt;）&quot;">​</a></h4><h4 id="多单词组成时-所有单词的首字母大写-xxxyyyzzz-例如-tankshotgame" tabindex="-1">多单词组成时，所有单词的<span style="color:red;">首字母大写</span>：XxxYyyZzz 例如：TankShotGame <a class="header-anchor" href="#多单词组成时-所有单词的首字母大写-xxxyyyzzz-例如-tankshotgame" aria-label="Permalink to &quot;多单词组成时，所有单词的&lt;span style=&quot;color:red&quot;&gt;首字母大写&lt;/span&gt;：XxxYyyZzz 例如：TankShotGame&quot;">​</a></h4></blockquote><h3 id="变量名、方法名" tabindex="-1">变量名、方法名 <a class="header-anchor" href="#变量名、方法名" aria-label="Permalink to &quot;变量名、方法名&quot;">​</a></h3><blockquote><h4 id="驼峰命名法-小驼峰" tabindex="-1">驼峰命名法（<span style="color:red;">小驼峰</span>） <a class="header-anchor" href="#驼峰命名法-小驼峰" aria-label="Permalink to &quot;驼峰命名法（&lt;span style=&quot;color:red&quot;&gt;小驼峰&lt;/span&gt;）&quot;">​</a></h4><h4 id="多单词组成时-第一个单词首字母小写-第二个单词开始每个单词首字母大写-xxxyyyzzz-例如-tankshotgame" tabindex="-1">多单词组成时，<span style="color:red;">第一个</span>单词首字母<span style="color:red;">小写</span>，<span style="color:red;">第二个单词开始</span>每个单词<span style="color:red;">首字母大写</span>：xxxYyyZzz 例如：tankShotGame <a class="header-anchor" href="#多单词组成时-第一个单词首字母小写-第二个单词开始每个单词首字母大写-xxxyyyzzz-例如-tankshotgame" aria-label="Permalink to &quot;多单词组成时，&lt;span style=&quot;color:red&quot;&gt;第一个&lt;/span&gt;单词首字母&lt;span style=&quot;color:red&quot;&gt;小写&lt;/span&gt;，&lt;span style=&quot;color:red&quot;&gt;第二个单词开始&lt;/span&gt;每个单词&lt;span style=&quot;color:red&quot;&gt;首字母大写&lt;/span&gt;：xxxYyyZzz 例如：tankShotGame&quot;">​</a></h4></blockquote><h3 id="常量名" tabindex="-1">常量名 <a class="header-anchor" href="#常量名" aria-label="Permalink to &quot;常量名&quot;">​</a></h3><blockquote><h4 id="所有字母都大写-不同单词用下划线连接-xxx-yyy-zzz-例如-tax-rate" tabindex="-1">所有<span style="color:red;">字母都大写</span>，不同单词用<span style="color:red;">下划线连接</span>：XXX_YYY_ZZZ 例如：TAX_RATE <a class="header-anchor" href="#所有字母都大写-不同单词用下划线连接-xxx-yyy-zzz-例如-tax-rate" aria-label="Permalink to &quot;所有&lt;span style=&quot;color:red&quot;&gt;字母都大写&lt;/span&gt;，不同单词用&lt;span style=&quot;color:red&quot;&gt;下划线连接&lt;/span&gt;：XXX_YYY_ZZZ 例如：TAX_RATE&quot;">​</a></h4></blockquote><hr><h2 id="保留字" tabindex="-1">保留字 <a class="header-anchor" href="#保留字" aria-label="Permalink to &quot;保留字&quot;">​</a></h2><blockquote><h4 id="现有-java-版本尚未使用-但以后版本可能会作为关键字使用。在标识符命名时要避免使用这些保留字" tabindex="-1">现有 Java 版本尚未使用，但以后版本可能会作为关键字使用。在<span style="color:red;">标识符命名时要避免使用这些保留字</span> <a class="header-anchor" href="#现有-java-版本尚未使用-但以后版本可能会作为关键字使用。在标识符命名时要避免使用这些保留字" aria-label="Permalink to &quot;现有 Java 版本尚未使用，但以后版本可能会作为关键字使用。在&lt;span style=&quot;color:red&quot;&gt;标识符命名时要避免使用这些保留字&lt;/span&gt;&quot;">​</a></h4></blockquote><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E06C75;">byValue、cast、future、 generic、 inner、 operator、 outer、 rest、 var 、 </span><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">goto</span><span style="--shiki-light:#24292E;--shiki-dark:#E06C75;"> 、cons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',21)])])}const q=t(r,[["render",n]]);export{p as __pageData,q as default};
